using System;
using UnityEngine;

namespace Astrea;

public class HeveliusOmensHandler : ReferenceSingleton<HeveliusOmensHandler>
{
	[NonSerialized]
	public Action GlowingReactorOmenAction;

	[NonSerialized]
	public Action GlowingReactorBarrierLightShieldOmenAction;

	[NonSerialized]
	public Action GlowingReactorIncorruptibleLightShieldOmenAction;

	[NonSerialized]
	public Action EnergyAbsorberOmenAction;

	[NonSerialized]
	public Action<HeveliusLinkEffect, int, GameObject, GameObject> LinkDuplicateAction;

	[NonSerialized]
	public Action CarapaceVorpalPlateAction;

	[NonSerialized]
	public Action<GameObject, int> OnEnemyCorruptionBlockedAction;

	[NonSerialized]
	public Action<GameObject> ShiningApparatusOmenAction;

	[NonSerialized]
	public Action StaffCapacitorFeedbackAction;

	public bool IsGlowingReactorOmenActive()
	{
		if (GlowingReactorOmenAction != null)
		{
			GlowingReactorOmenAction();
			return true;
		}
		return false;
	}

	public void ActivateEnergyAbsorberOmen()
	{
		if (EnergyAbsorberOmenAction != null)
		{
			EnergyAbsorberOmenAction();
		}
	}

	public void ActivateLinkDuplicateAction(HeveliusLinkEffect heveliusLinkEffect, int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (LinkDuplicateAction != null)
		{
			LinkDuplicateAction(heveliusLinkEffect, effectAmount, effectOwner, source);
		}
	}

	public void ActivateCarapaceVorpalPlate()
	{
		if (ReferenceSingleton<AssetsReference>.Instance.MapHandler.IsBattleSetup && CarapaceVorpalPlateAction != null)
		{
			CarapaceVorpalPlateAction();
		}
	}

	public void OnEnemyCorruptionBlocked(GameObject enemyTarget, int corruptionBlockedAmount)
	{
		OnEnemyCorruptionBlockedAction?.Invoke(enemyTarget, corruptionBlockedAmount);
	}

	public void OnSentinelsCorruptedActivateShiningApparatus(GameObject sentinelTarget)
	{
		ShiningApparatusOmenAction?.Invoke(sentinelTarget);
	}
}
